from lib import *
S = SS('w76')
steps = [
    step("拆开 example.com 的分块响应。响应头里 Transfer-Encoding: chunked,没有 Content-Length。消息体共 589 字节,只有 1 个数据块,块大小 577(十六进制 241,正好是 w74 里看到的第一行 \"241\\r\\n\");实际内容 577 字节,框架开销 12 字节:块长度行 \"241\\r\\n\" 5 字节 + 块数据后的 CRLF 2 字节 + 结束标记 \"0\\r\\n\\r\\n\" 5 字节。内容以 <!doctype html> 开头、以 </body></html> 结尾,最后一个块之后是长度为 0 的块 + 空的 trailer + 空行,标志消息体结束。", t=tl(S(1)), mark=lidx(S(1), '消息体共 589 字节', '内容开头'), done=lidx(S(1), '响应头里'), b=bars([['内容', 577, '577 字节'], ['框架开销', 12, '12 字节']], 577, mark=[1], done=[0]), kv=KV([['块数', '1,大小 577(0x241)'], ['框架开销', '12 字节 = 5 + 2 + 5'], ['结束标记', '0 CRLF CRLF']], ['框架开销'])),
    step("分块的开销取决于块大小:同样 100000 字节内容。Content-Length:消息体 100000 字节,开销 0。chunked 每块 100 字节:106005 字节,开销 6005 字节(6.00%);每块 1 KiB:100691 字节,开销 691(0.69%);每块 16 KiB:100060 字节,开销 60(0.06%)。块越小,每块的长度行和 CRLF 占比越高;合理的块大小下开销可以忽略。", t=tl(S(2)), mark=lidx(S(2), 'chunked,每块 100 字节', 'chunked,每块 1 KiB', 'chunked,每块 16 KiB'), done=lidx(S(2), 'Content-Length   '), b=bars([['每块 100 字节', 6.00, '6.00%'], ['每块 1 KiB', 0.69, '0.69%'], ['每块 16 KiB', 0.06, '0.06%'], ['Content-Length', 0, '0%']], 6.0, mark=[0], done=[1, 2, 3]), kv=KV([['每块 100 B', '开销 6005 字节(6.00%)'], ['每块 1 KiB', '691 字节(0.69%)'], ['每块 16 KiB', '60 字节(0.06%)']], ['每块 100 B'])),
    step("chunked 的真正用处:边生成边发,不用事先知道总长度。服务器每 200 ms 生成一块,共 5 块:客户端收到的数据到达时刻依次是 0、205、409、610、813、1016 ms(第一个 66 字节是响应头加第一块,之后每块 26 字节,最后 31 字节含结束标记),客户端可以边收边处理。用 Content-Length 的做法,服务器必须先生成完整内容、算出长度才能发头部:同样的内容,第一个字节要到 1001 ms 才到,而且 159 字节在同一时刻全部到达。流式输出(日志、大文件生成、代理转发)就靠这个。", t=tl(S(3)), mark=lidx(S(3), 'chunked:客户端收到', 'Content-Length(服务器要先生成'), done=lidx(S(3), 'chunked:客户端收到'), b=bars([['chunked 第 1 个字节', 0, '0 ms'], ['chunked 最后一块', 1016, '1016 ms'], ['Content-Length 第 1 个字节', 1001, '1001 ms']], 1016, mark=[2], done=[0, 1]), kv=KV([['chunked', '0 / 205 / 409 / 610 / 813 / 1016 ms 陆续到达'], ['Content-Length', '1001 ms 才开始,一次到齐']], ['chunked'])),
    step("既没有 Content-Length 也没有 chunked 的响应,消息体以“连接关闭”为终点(HTTP/1.0 的做法)。服务器 0 ms 时就发完了 100 字节,然后保持连接 2 秒再关:客户端在 0 ms 收到了全部 100 字节,却无从知道这是不是全部,一直等到服务器在 2001 ms 关闭连接才能确定响应结束。这样的响应不可能复用连接——所以持久连接要求响应必须有明确的长度(Content-Length 或 chunked)。", t=tl(S(4)), mark=lidx(S(4), '100 字节在 0 ms'), done=lidx(S(4), '100 字节在 0 ms'), b=bars([['数据到齐', 0, '0 ms'], ['客户端能确认结束', 2001, '2001 ms']], 2001, mark=[1], done=[0]), kv=KV([['数据', '0 ms 到齐'], ['结束判定', '2001 ms 服务器关连接才知道'], ['能否复用连接', '不能']], ['结束判定'])),
    step("长度写错和截断检测。用 Python 的 http.client 当客户端。Content-Length: 1000 却只发 600 字节就关连接 → IncompleteRead(已读 600,还缺 400):被发现了。chunked 发了一个块后没有发结尾的 0 块就关连接 → IncompleteRead(已读 256):也被发现了。没有长度、发 600 字节就关 → 正常读到 600 字节,状态 200:读起来一切正常,但客户端无法判断是否被截断——这是 close 定界的危险。Content-Length: 500 却发了 1000 字节 → 客户端只读 500 字节;多出的字节留在连接上。错位演示:服务器对第 1 个请求声明 Content-Length: 5 却在 \"hello\" 后面多发了 11 字节 \"WORLD-EXTRA\",随后才是第 2 个响应:客户端读完 hello,接下来的字节是 \"WORLD-EXTRAHTTP/1.1 200 OK…\",被当作第 2 个响应的开头,不是合法状态行——连接上的响应从此错位。这就是请求走私 / 响应拆分漏洞的根源:前后两个角色对“消息在哪里结束”的理解不一致。", t=tl(S(5)), mark=lidx(S(5), 'Content-Length: 1000', 'chunked,发了一个块', '没有长度,发 600', '响应错位演示'), done=lidx(S(5), 'Content-Length: 500'), kv=KV([['CL=1000,只发 600', 'IncompleteRead:被发现'], ['chunked 缺结尾块', 'IncompleteRead:被发现'], ['close 定界被截断', '无法发现'], ['长度写小', '多余字节污染后面的响应']], ['close 定界被截断'])),
]
A = mkartw('w76', 76, '网络协议,HTTP,分块传输,Transfer-Encoding,Content-Length,请求走私,真实验证,动画演示',
    '实测 HTTP 消息体怎么划界:example.com 的 589 字节分块响应只有 1 个 577 字节的块、框架开销 12 字节;100000 字节每块 100 字节开销 6.00% 而每块 16 KiB 只有 0.06%;chunked 让数据 0~1016 ms 陆续到达而 Content-Length 要等 1001 ms;缺长度的响应要等连接关闭才结束;长度写错、截断、错位各是什么后果。',
    'HTTP 的消息体到哪里结束?答案只有三种:Content-Length 写明长度、Transfer-Encoding: chunked 分块、或者干脆等连接关闭。这篇逐个看它们的字节、开销和用处,再故意写错长度,看错位和截断是怎么发生的——这也是请求走私类漏洞的根源。',
    [('12 字节', 'example.com 的 589 字节分块响应里框架开销'), ('6.00% → 0.06%', '同样 100000 字节内容,chunked 每块 100 字节与每块 16 KiB 的框架开销'), ('1001 ms vs 0 ms', 'Content-Length 方式第一个字节到达时间与 chunked 方式的对比')],
    [('chunked 的格式', '<p>每块:十六进制长度行 CRLF + 数据 + CRLF;长度 0 的块结束,可带 trailer。</p>'),
     ('开销', '<p>块越小开销越高:每块 100 字节 6.00%,16 KiB 0.06%。</p>'),
     ('流式', '<p>chunked 允许边生成边发,不必先知道总长度。</p>'),
     ('close 定界', '<p>没有长度的响应要等连接关闭才结束,无法复用连接,也无法发现被截断。</p>'),
     ('长度不一致', '<p>写小了,多余字节污染后面的响应;截断在有长度的响应里能被发现。</p>')],
    steps,
    [ENV_W + '。第一节是 example.com:80 的真实响应;第二至五节用本机脚本化的服务器(逐段按延迟发送预设字节)和 Python 的 http.client / 原始套接字当客户端;各框架开销一部分是算出来的(第二节的 100 字节 / 1 KiB / 16 KiB 是实测消息体长度减 100000)',
     '没有验证:chunked 的 chunk extension 与 trailer 的使用(只看到空 trailer);Content-Length 与 Transfer-Encoding 同时出现时各家服务器的取舍(请求走私的实际利用);HTTP/2 里没有分块,用帧划界(见后面的 HTTP/2 篇);压缩与分块组合;浏览器对错误长度的容忍度'],
    '分块传输与 Content-Length')
